package com.kuzhi.findme.compat.waystones;

import com.kuzhi.findme.compat.waystones.WaystoneDestination;
import com.kuzhi.findme.compat.waystones.WaystonesApiBridge;
import java.util.List;
import java.util.UUID;
import java.util.function.Consumer;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraftforge.fml.ModList;
import org.apache.maven.artifact.versioning.ArtifactVersion;
import org.apache.maven.artifact.versioning.DefaultArtifactVersion;

public final class WaystonesIntegration {
    private static final ArtifactVersion MINIMUM_API_VERSION = new DefaultArtifactVersion("14.1");

    private WaystonesIntegration() {
    }

    public static boolean available() {
        return ModList.get().getModContainerById("waystones").map(container -> container.getModInfo().getVersion().compareTo((Object)MINIMUM_API_VERSION) >= 0).orElse(false);
    }

    public static List<WaystoneDestination> destinations(ServerPlayer player) {
        return WaystonesIntegration.available() ? WaystonesApiBridge.destinations(player) : List.of();
    }

    public static boolean isActivated(ServerPlayer player, UUID waystoneUuid) {
        return WaystonesIntegration.available() && WaystonesApiBridge.isActivated(player, waystoneUuid);
    }

    public static void teleport(ServerPlayer player, LivingEntity mount, UUID waystoneUuid, Consumer<List<Entity>> success, Consumer<Component> failure) {
        if (!WaystonesIntegration.available()) {
            failure.accept((Component)Component.m_237115_((String)"message.find_me.waystones_unavailable"));
            return;
        }
        WaystonesApiBridge.teleport(player, mount, waystoneUuid, success, failure);
    }

    public static void syncMountedState(ServerPlayer player, LivingEntity mount) {
        if (WaystonesIntegration.available()) {
            WaystonesApiBridge.syncMountedState(player, mount);
        }
    }
}

