}

static Map<String, List<String>> parseDialogueOverrides(List<? extends String> entries) {
    LinkedHashMap<String, List> parsed = new LinkedHashMap<String, List>();
    for (String string : entries) {
        String context = Config.dialogueContext(string);
        if (context == null) continue;
        List lines = parsed.computeIfAbsent(context, ignored -> new ArrayList());
        String value2 = string.substring(string.indexOf(61) + 1).trim();
        if (value2.isBlank()) continue;
        lines.add(value2);
    }
    LinkedHashMap immutable = new LinkedHashMap();
    parsed.forEach((key, value) -> immutable.put(key, List.copyOf(value)));
    return Map.copyOf(immutable);
}

